import{_ as s,C as n,o as t,c as i,a2 as o,b as d,w as r,a as c,E as l,a3 as g}from"./chunks/framework.Cmuzzkcw.js";const v=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/index.md","filePath":"recipes/index.md"}'),h={name:"recipes/index.md"};function p(u,e,m,f,b,y){const a=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Most framework docs tell you <em>how</em> to wire a single endpoint. <strong>Recipes</strong> are the opposite: they are <strong>runnable stories</strong>—whole applications in this repo that you can <strong>run</strong>, <strong>read end-to-end</strong>, and <strong>steal from</strong> when your own service needs the same shape of problem.</p><p>Each recipe is a <strong>vertical slice</strong>: HTTP surface, application services, and persistence (or transport) live under one roof, usually as <strong><code>src/modules/&lt;feature&gt;/</code></strong>. Nothing is a throwaway “hello world”; the layout is the same layout you would defend in a design review—just smaller.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>BananaJS is opinionated about <strong>structure</strong> (decorators, Zod, <code>SuccessResponse</code>, modules with <strong>tsyringe</strong>). Recipes show what that structure <strong>feels like</strong> when the domain is real enough to need <strong>auth</strong>, <strong>pagination</strong>, <strong>two databases</strong>, or <strong>WebSockets</strong>—without hiding the boring parts (env files, Docker, lint, CLI).</p><p>If <a href="/banana-universe/guide/getting-started.html">Getting started</a> gets you a blank canvas, recipes are <strong>finished sketches</strong> you trace.</p><h2 id="how-to-pick-a-recipe" tabindex="-1">How to pick a recipe <a class="header-anchor" href="#how-to-pick-a-recipe" aria-label="Permalink to &quot;How to pick a recipe&quot;">​</a></h2><p>Ask what you are trying to <strong>prove</strong> first—not which database you like on paper.</p><table tabindex="0"><thead><tr><th>If you want to…</th><th>Start with</th></tr></thead><tbody><tr><td>Ship a <strong>relational</strong> API with layered modules, auth, and optional traces</td><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-rest-postgresql" target="_blank" rel="noreferrer">example-rest-postgresql</a></td></tr><tr><td>Prefer <strong>MongoDB</strong> and Mongoose with Zod on the wire</td><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-rest-mongodb" target="_blank" rel="noreferrer">example-rest-mongodb</a></td></tr><tr><td>See <strong>TypeORM and Mongoose in one process</strong> without blending concerns—<strong>one ORM per module</strong></td><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-rest-dual-orm" target="_blank" rel="noreferrer">example-rest-dual-orm</a></td></tr><tr><td>Run <strong>Fastify</strong> next to Express or explore a hybrid HTTP stack</td><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-fastify" target="_blank" rel="noreferrer">example-fastify</a></td></tr><tr><td>Add <strong>WebSockets</strong> beside REST</td><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-websocket-chat" target="_blank" rel="noreferrer">example-websocket-chat</a></td></tr><tr><td>Model <strong>multi-tenancy</strong> and <strong>ABAC-style</strong> authorization (<code>@Can</code>)</td><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-multitenant" target="_blank" rel="noreferrer">example-multitenant</a></td></tr></tbody></table><p>Everything in the table below links to the same apps with a bit more detail.</p><h2 id="soft-architecture-what-stays-stable" tabindex="-1">Soft architecture: what stays stable <a class="header-anchor" href="#soft-architecture-what-stays-stable" aria-label="Permalink to &quot;Soft architecture: what stays stable&quot;">​</a></h2><p>Recipes are not identical, but they <strong>rhyme</strong>. That is intentional: your team should recognize the <strong>same moves</strong> in every app.</p>',12)),(t(),d(g,null,{default:r(()=>[l(a,{id:"mermaid-95",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20boundary%20%5BOne%20feature%20module%5D%0A%20%20%20%20C%5BController%20HTTP%5D%0A%20%20%20%20S%5BServices%20%2F%20use-cases%5D%0A%20%20%20%20D%5BDomain%20ports%20%26%20DTOs%5D%0A%20%20%20%20P%5BPersistence%20adapter%5D%0A%20%20end%0A%20%20C%20--%3E%20S%0A%20%20S%20--%3E%20D%0A%20%20D%20--%3E%20P%0A%20%20style%20C%20fill%3A%230f2440%2Cstroke%3A%23fdb913%2Ccolor%3A%23f8fafc%0A%20%20style%20S%20fill%3A%23132a45%2Cstroke%3A%235b7a8c%2Ccolor%3A%23f8fafc%0A%20%20style%20D%20fill%3A%23132a45%2Cstroke%3A%235b7a8c%2Ccolor%3A%23f8fafc%0A%20%20style%20P%20fill%3A%231a3a52%2Cstroke%3A%23fdb913%2Ccolor%3A%23f8fafc%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ul><li><strong>Modules, not loose controllers</strong> — Prefer <strong><code>defineBananaAppOptions({ modules: [...] })</code></strong> and <strong><code>createModule</code></strong> so each feature brings its own <strong>tsyringe</strong> child container. A flat <strong><code>controllers</code></strong> list still works for small apps; recipes lean toward <strong>modules</strong> because that is where the framework’s <strong>enterprise-shaped</strong> DX pays off. See <a href="/banana-universe/guide/layered-architecture.html">Layered architecture</a> and <a href="/banana-universe/guide/domain-and-persistence.html">Domain &amp; persistence</a> for how slices meet storage.</li><li><strong>One HTTP class per module</strong> — Split modules if the API surface forks (e.g. public vs admin); don’t grow a “god controller.”</li><li><strong>Validation at the edge</strong> — <code>@Body</code>, <code>@Params</code>, <code>@Query</code>, <code>@Headers</code> with <strong>Zod</strong> keep failures <strong>400</strong> and predictable.</li><li><strong>Cross-cutting concerns</strong> — Auth guards, tenancy, and OpenAPI sit in <strong>options</strong> and <strong>decorators</strong> (<code>@Auth</code>, <code>@Public</code>, <code>@Roles</code>, <code>@Can</code>); see <a href="/banana-universe/integrations/auth.html">Authentication</a> when you wire identity.</li></ul><div class="tip custom-block"><p class="custom-block-title">Greenfield vs exploration</p><p>Use <strong><code>bananajs new</code></strong> (<a href="/banana-universe/guide/getting-started.html">Getting started</a>) to <strong>generate</strong> a matching layout. Use <strong>recipes</strong> when you want to <strong>read</strong> a full repo layout that already made the decisions.</p></div><h2 id="conventions-shared-across-recipes" tabindex="-1">Conventions (shared across recipes) <a class="header-anchor" href="#conventions-shared-across-recipes" aria-label="Permalink to &quot;Conventions (shared across recipes)&quot;">​</a></h2><ul><li><strong>Layout</strong> — <code>src/modules/&lt;feature&gt;/</code> per vertical slice: controller, DTOs, services, infrastructure. <strong>Dotted role names</strong> for feature files (e.g. <code>Catalog.controller.ts</code>, <code>CatalogItem.entity.ts</code>, <code>Article.service.ts</code>); keep <strong><code>main.ts</code></strong>, <strong><code>bootstrap.ts</code></strong>, and barrel <strong><code>index.ts</code></strong> in <strong>lowercase</strong>. In <strong><code>createModule</code></strong>, list only <strong>non-controller</strong> providers—the <strong><code>controller</code></strong> field registers the HTTP class; <strong>do not</strong> duplicate it in <strong><code>providers</code></strong>. Domain persistence contracts use <strong><code>domain/&lt;Entity&gt;.mapper.ts</code></strong> (repository port) or <strong><code>domain/&lt;Entity&gt;.repository.ts</code></strong>; combine list/query Zod shapes into the feature <strong><code>*.dto.ts</code></strong> instead of scattering one-off query files.</li><li><strong>Shared code</strong> — Cross-cutting helpers under <code>src/lib/</code> (e.g. <code>BearerAuthGuard.ts</code>).</li><li><strong>Environment</strong> — Copy <code>.env.example</code> → <code>.env</code>; entry loads <strong><code>dotenv</code></strong> (<code>import &#39;dotenv/config&#39;</code> in <code>main.ts</code>).</li><li><strong>Development</strong> — <code>npm run dev</code> uses <strong><code>tsx watch</code></strong>; <code>npm run build</code> / <code>npm start</code> for production-style runs.</li><li><strong>Quality</strong> — ESLint 9 (type-aware TypeScript) + Prettier; <code>npm run lint</code>, <code>npm run format</code>. CLI-generated apps align with <strong>Prettier</strong> tab width <strong>4</strong>, <strong><code>.editorconfig</code></strong>, and optional Swagger at <strong><code>/api-docs</code></strong> (see <a href="/banana-universe/guide/getting-started.html">Getting started</a>).</li><li><strong>CLI</strong> — <code>@banana-universe/bananajs-cli</code> as a devDependency (<code>bananajs</code>, <code>bjs</code>).</li></ul><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recipe</th><th>Stack</th><th>What it demonstrates</th></tr></thead><tbody><tr><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-rest-postgresql" target="_blank" rel="noreferrer">example-rest-postgresql</a></td><td>SQL (PostgreSQL)</td><td>Layered <code>modules/catalog</code>, auth, pagination, optional observability, API docs</td></tr><tr><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-rest-mongodb" target="_blank" rel="noreferrer">example-rest-mongodb</a></td><td>MongoDB</td><td><code>modules/articles</code>, Mongoose + <code>@Body(Zod)</code> (see app README for deployment)</td></tr><tr><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-rest-dual-orm" target="_blank" rel="noreferrer">example-rest-dual-orm</a></td><td>SQL + MongoDB</td><td><strong>One ORM per module</strong>: <code>widgets</code> (TypeORM), <code>tags</code> (Mongoose); shared bootstrap</td></tr><tr><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-fastify" target="_blank" rel="noreferrer">example-fastify</a></td><td>Fastify + Express</td><td><code>modules/health</code>, hybrid HTTP via <code>@fastify/express</code></td></tr><tr><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-websocket-chat" target="_blank" rel="noreferrer">example-websocket-chat</a></td><td>WebSockets</td><td><code>modules/health</code> + <code>modules/chat</code>, WebSocket plugin alongside HTTP</td></tr><tr><td><a href="https://github.com/surya-manne/banana-universe/tree/main/apps/example-multitenant" target="_blank" rel="noreferrer">example-multitenant</a></td><td>SQL + tenancy</td><td><code>modules/note</code>, per-tenant data and <code>@Can</code> ABAC-style checks</td></tr></tbody></table><p>Each recipe ships with a <strong><code>README.md</code></strong>, <strong><code>.env.example</code></strong> where it matters, and <strong><code>docker-compose.yml</code></strong> when a database (or similar) is part of the story.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/banana-universe/guide/philosophy.html">Philosophy</a> — why BananaJS optimizes for clarity and AI-friendly structure</li><li><a href="/banana-universe/guide/layered-architecture.html">Layered architecture</a> — how slices map to layers</li><li><a href="/banana-universe/integrations/typeorm.html">Integrations</a> — ORMs, validation, auth, observability</li><li><a href="/banana-universe/tooling/cli.html">Tooling</a> — <strong><code>bananajs</code></strong> / <strong><code>bjs</code></strong> commands that recipes already include</li></ul>',9))])}const x=s(h,[["render",p]]);export{v as __pageData,x as default};
